const crypto = require('crypto');
const isEmail = $json.subject !== undefined || $json.from !== undefined;
const sender = isEmail ? ($json.from?.emailAddress?.address || $json.from || '') : ($json.from?.user?.mail || $json.from?.user?.userPrincipalName || '');
const payload = {
  action: 'ticket.create_from_message',
  channel: isEmail ? 'email' : 'teams',
  sender: String(sender).toLowerCase(),
  subject: isEmail ? ($json.subject || '') : '',
  body: isEmail ? ($json.bodyPreview || $json.body?.content || '') : ($json.body?.content || ''),
  external_id: $json.id || ''
};
const raw = JSON.stringify(payload);
const ts = String(Math.floor(Date.now()/1000));
const sig = 'sha256=' + crypto.createHmac('sha256', $env.PORTAL_INBOUND_SECRET).update(ts + '.' + raw).digest('hex');
return [{ json: { raw, ts, sig, eventId: 'intake-' + (payload.external_id || Date.now()) } }];
